import{_ as i,a0 as e,w as r,s as l,ao as a,I as s,x as u,a1 as p,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"Linux 有問必答：如何通過代理服務器安裝 Ubuntu 桌面版 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 有問必答：如何通過代理服務器安裝 Ubuntu 桌面版 | LCTT (201603) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 有問必答：如何通過代理服務器安裝 Ubuntu 桌面版 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 有問必答：如何通過代理服務器安裝 Ubuntu 桌面版 | LCTT (201603) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201603/20151105 Linux FAQs with Answers--How to install Ubuntu desktop behind a proxy","title":"Linux 有問必答：如何通過代理服務器安裝 Ubuntu 桌面版","tag":"201603","desc":""},"relativePath":"201603/20151105 Linux FAQs with Answers--How to install Ubuntu desktop behind a proxy.md","filePath":"[post].md"}'),b={name:"201603/20151105 Linux FAQs with Answers--How to install Ubuntu desktop behind a proxy.md"};function d(m,t,c,x,g,_){const n=e("Link");return r(),l("div",null,[t[13]||(t[13]=a(`<h1 id="linux-有問必答-如何通過代理服務器安裝-ubuntu-桌面版" tabindex="-1">Linux 有問必答：如何通過代理服務器安裝 Ubuntu 桌面版 <a class="header-anchor" href="#linux-有問必答-如何通過代理服務器安裝-ubuntu-桌面版" aria-label="Permalink to “Linux 有問必答：如何通過代理服務器安裝 Ubuntu 桌面版”">​</a></h1><blockquote><p><strong>問題</strong>: 我的電腦通過 HTTP 代理連接到公司網絡。當我嘗試從 CD-ROM 在計算機上安裝 Ubuntu 桌面時，在檢索文件時安裝程序會被掛起，檢索則不會完成，這可能是由於代理造成的。然而問題是，Ubuntu 的安裝程序從不要求我在安裝過程中配置代理。那我該怎麼使用代理來安裝 Ubuntu 桌面？</p></blockquote><p>與 Ubuntu 服務器不太一樣，安裝 Ubuntu 桌面幾乎都是自動安裝，沒有留下太多自定義的空間，如自定義磁盤分區，手動網絡設置，包選擇等等。儘管非常簡單，一鍵安裝被認為是用户友好的，它不需要用户尋找“高級安裝模式”來定製自己的 Ubuntu 桌面。</p><p>此外，Ubuntu 默認桌面的安裝程序中一個大問題是代理設置。如果你的計算機連接在一個代理上，你會發現 Ubuntu 安裝時會卡在準備下載文件處。</p><p><img src="https://c2.staticflickr.com/6/5683/22195372232_cea81a5e45_c.jpg" alt=""></p><p>這篇文章描述瞭如何解決當使用代理時 Ubuntu <strong>安裝程序的限制和安裝 Ubuntu 桌面</strong>。</p><p>其基本思路如下。不是直接使用 Ubuntu 的安裝程序開始安裝，首先進入 live Ubuntu 桌面，配置代理服務器，最後從 live 桌面手動啓動 Ubuntu 的安裝程序。以下是程序的安裝步驟。</p><p>從 CD/DVD 或 USB 啓動 Ubuntu 桌面後，點擊第一個歡迎屏幕上的&quot;Try Ubuntu&quot;。</p><p><img src="https://c1.staticflickr.com/1/586/22195371892_3816ba09c3_c.jpg" alt=""></p><p>一旦進入 live Ubuntu 桌面，點擊左側設置圖標。</p><p><img src="https://c1.staticflickr.com/1/723/22020327738_058610c19d_c.jpg" alt=""></p><p>進入 Network 菜單。</p><p><img src="https://c2.staticflickr.com/6/5675/22021212239_ba3901c8bf_c.jpg" alt=""></p><p>手動配置代理服務器。</p><p><img src="https://c1.staticflickr.com/1/735/22020025040_59415e0b9a_c.jpg" alt=""></p><p>接下來，打開一個終端。</p><p><img src="https://c2.staticflickr.com/6/5642/21587084823_357b5c48cb_c.jpg" alt=""></p><p>通過輸入以下命令切換到 root 用户：</p><pre><code>$ sudo su
</code></pre><p>最後，在 root 用户下輸入以下命令。</p><pre><code># ubiquity gtk_ui
</code></pre><p>然後將啓動基於 GUI 的 Ubuntu 安裝程序。</p><p><img src="https://c1.staticflickr.com/1/723/22020025090_cc64848b6c_c.jpg" alt=""></p><p>繼續安裝其餘部分。</p><p><img src="https://c1.staticflickr.com/1/628/21585344214_447020e9d6_c.jpg" alt=""></p><hr>`,26)),s("p",null,[t[1]||(t[1]=u("via: ",-1)),p(n,{href:"http://ask.xmodulo.com/install-ubuntu-desktop-behind-proxy.html"},{default:o(()=>[...t[0]||(t[0]=[u("http://ask.xmodulo.com/install-ubuntu-desktop-behind-proxy.html",-1)])]),_:1})]),s("p",null,[t[5]||(t[5]=u("作者：",-1)),p(n,{href:"http://ask.xmodulo.com/author/nanni"},{default:o(()=>[...t[2]||(t[2]=[u("Dan Nanni",-1)])]),_:1}),t[6]||(t[6]=u(" 譯者：",-1)),p(n,{href:"https://github.com/strugglingyouth"},{default:o(()=>[...t[3]||(t[3]=[u("strugglingyouth",-1)])]),_:1}),t[7]||(t[7]=u(" 校對：",-1)),p(n,{href:"https://github.com/wxy"},{default:o(()=>[...t[4]||(t[4]=[u("wxy",-1)])]),_:1})]),s("p",null,[t[10]||(t[10]=u("本文由 ",-1)),p(n,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[8]||(t[8]=[u("LCTT",-1)])]),_:1}),t[11]||(t[11]=u(" 原創編譯，",-1)),p(n,{href:"https://linux.cn/"},{default:o(()=>[...t[9]||(t[9]=[u("Linux中國",-1)])]),_:1}),t[12]||(t[12]=u(" 榮譽推出",-1))])])}const T=i(b,[["render",d]]);export{k as __pageData,T as default};
